CREATE TABLE IF NOT EXISTS counts(tool TEXT PRIMARY KEY, count INTEGER NOT NULL DEFAULT 0 CHECK(count >= 0));
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY, tool TEXT NOT NULL, created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS events_created ON events(created);
CREATE TABLE IF NOT EXISTS limits(key TEXT PRIMARY KEY, hits INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS limits_expires ON limits(expires);
CREATE TABLE IF NOT EXISTS comments(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,name TEXT NOT NULL,body TEXT NOT NULL,created INTEGER NOT NULL,hidden INTEGER NOT NULL DEFAULT 0 CHECK(hidden IN (0,1)));
CREATE INDEX IF NOT EXISTS comments_public ON comments(hidden,seq DESC);
